// Filmstreifen einer Animation: Bilder im Zeitverlauf + Messung von Layout-Sprüngen (CLS) und langen Tasks.
// Aufruf: node film.mjs <url> <ausgabeordner> [breite=1440] [--el=<css>] [--reduced] [--hover=<css>]
//   ohne --el: Bilder direkt nach dem Laden (Hero-Choreografie)
//   --el:      erst zum Element scrollen, dann Bilder (Scroll-Animationen)
//   --hover:   nach dem Film über das Element fahren und Hover-Zustand aufnehmen
//   --reduced: prefers-reduced-motion simulieren (Inhalt muss trotzdem sofort sichtbar sein)
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const [url, out = "./film", breiteArg = "1440", ...rest] = process.argv.slice(2);
const w = Number(breiteArg) || 1440;
const el = rest.find((a) => a.startsWith("--el="))?.slice(5);
const hover = rest.find((a) => a.startsWith("--hover="))?.slice(8);
const reduced = rest.includes("--reduced");
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({
  viewport: { width: w, height: w < 700 ? 844 : 900 },
  reducedMotion: reduced ? "reduce" : "no-preference",
});
// Cookie-Banner vorab ausblenden, damit er nichts verdeckt
await ctx.addInitScript(() => {
  try { localStorage.setItem("cookie-consent", "necessary"); } catch {}
  new PerformanceObserver((l) => { for (const e of l.getEntries()) if (!e.hadRecentInput) window.__cls = (window.__cls || 0) + e.value; }).observe({ type: "layout-shift", buffered: true });
  new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__long = (window.__long || 0) + 1; }).observe({ type: "longtask", buffered: true });
});
const page = await ctx.newPage();
const fehler = [];
page.on("console", (m) => m.type() === "error" && fehler.push(m.text()));
page.on("pageerror", (e) => fehler.push(String(e)));

const zeiten = [0, 150, 300, 500, 800, 1200, 2000];
await page.goto(url, { waitUntil: "commit", timeout: 180000 });
await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 1500 }).catch(() => {});
const tag = (el || "laden").replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "").slice(0, 40);

if (el) {
  await page.waitForLoadState("load");
  await page.waitForTimeout(800);
  const ziel = page.locator(el).first();
  // knapp unter den sichtbaren Bereich setzen, dann hineinscrollen, damit Eintritts-Animationen auslösen
  await ziel.evaluate((n) => window.scrollTo(0, n.getBoundingClientRect().top + window.scrollY - window.innerHeight - 50));
  await page.waitForTimeout(300);
  await ziel.evaluate((n) => window.scrollTo({ top: n.getBoundingClientRect().top + window.scrollY - 80, behavior: "instant" }));
}
let start = Date.now();
for (const t of zeiten) {
  const warte = t - (Date.now() - start);
  if (warte > 0) await page.waitForTimeout(warte);
  const datei = `${out}/w${w}${reduced ? "-reduced" : ""}-${tag}-t${String(t).padStart(4, "0")}.png`;
  await page.screenshot({ path: datei });
  console.log(datei);
}
if (hover) {
  await page.locator(hover).first().hover().catch(() => {});
  await page.waitForTimeout(400);
  const datei = `${out}/w${w}-${tag}-hover.png`;
  await page.screenshot({ path: datei });
  console.log(datei);

import Reveal from "@/components/ui/Reveal";
import { cn } from "@/components/ui/cn";

/**
 * Chronologie auf dunklem Grund. Eine Linie links, Jahr groß in eigener
 * Spalte (ab md), Karte rechts – ruhig lesbar statt Zickzack.
 * items: [{ jahr, titel, text, hervorgehoben? }]
 */
export default function Zeitleiste({ items = [] }) {
  return (
    <ol className="relative">
      <div aria-hidden="true" className="absolute bottom-8 left-[15px] top-3 w-px bg-gradient-to-b from-ov-400 via-white/15 to-ov-400 md:left-[120px]" />
      {items.map((e, i) => (
        <Reveal
          as="li"
          key={e.jahr}
          delay={i * 40}
          className="relative grid gap-x-16 pb-8 pl-11 last:pb-0 md:grid-cols-[88px_minmax(0,1fr)] md:pl-0"
        >
          <p className="ov-num pt-1 font-display text-[26px] font-extrabold leading-none tracking-tight text-white md:text-right md:text-[28px]">{e.jahr}</p>
          <span
            aria-hidden="true"
            className={cn(
              "absolute left-[5px] top-2 flex h-[21px] w-[21px] items-center justify-center rounded-full md:left-[110px]",
              e.hervorgehoben ? "bg-ov-500 shadow-[0_0_0_5px_rgba(102,153,51,0.25)]" : "bg-navy-950 ring-2 ring-ov-400/80"
            )}
          >
            <span className={cn("h-2 w-2 rounded-full", e.hervorgehoben ? "bg-white" : "bg-ov-400")} />
          </span>
          <div
            className={cn(
              "mt-3 rounded-2xl p-5 md:mt-0 md:p-6",
              e.hervorgehoben ? "bg-white/[0.08] ring-1 ring-ov-400/40" : "bg-white/[0.04] ring-1 ring-white/10"
            )}
          >
            <h3 className="font-display text-[17px] font-bold text-white">{e.titel}</h3>
            <p className="mt-1.5 text-[15px] leading-relaxed text-white/70">{e.text}</p>
          </div>
        </Reveal>
      ))}
    </ol>
  );
}
// Proportionale Zeitachse 2010 → heute auf dunklem Grund: Was die Gruppe seit
// wann tut. Nur Jahreszahlen aus den Meilensteinen (daten.js) – keine Mengen.

const START = 2010;

const SPUREN = [
  { ab: 2010, titel: "Planung & Bau von PV-Anlagen", text: "ÖKOVOLT, Türkheim", ton: "bg-white/80" },
  { ab: 2012, titel: "Eigene Solarparks in Betrieb", text: "Artern, Tilleda, ab 2013 Irsingen", ton: "bg-ov-300" },
  { ab: 2020, titel: "Projektentwicklung ÖkoInvest", text: "Freifläche, Agri-PV, Speicher", ton: "bg-ov-500" },
  { ab: 2023, titel: "Eigene Kraftwerksgesellschaften", text: "GFL, später HIL", ton: "bg-sun-300" },
];

export default function Zeitachse({ marken = [] }) {
  const heute = new Date().getFullYear();
  const ende = Math.max(heute, 2026);
  const pos = (j) => `${((j - START) / (ende - START)) * 100}%`;
  const ticks = [];
  for (let j = START; j <= ende; j += 2) ticks.push(j);

  return (
    <figure className="ov-flaeche-dunkel relative overflow-hidden p-5 sm:p-7 md:p-9">
      <figcaption className="flex flex-wrap items-baseline justify-between gap-x-6 gap-y-1">
        <span className="font-display text-[17px] font-bold text-white">Was die Gruppe seit wann tut</span>
        <span className="text-[13px] text-white/60">
          {START} bis heute
        </span>
      </figcaption>

      <div className="relative mt-7">
        {/* Raster */}
        <div aria-hidden="true" className="absolute inset-0">
          {ticks.map((j) => (
            <span key={j} className="absolute bottom-0 top-0 w-px bg-white/[0.07]" style={{ left: pos(j) }} />
          ))}
        </div>

        <ul className="relative space-y-4 sm:space-y-5">
          {SPUREN.map((s) => {
            const rechts = (s.ab - START) / (ende - START) > 0.5;
            const ausrichtung = rechts ? "sm:justify-end sm:text-right" : "sm:pl-[var(--x)]";
            return (
            <li key={s.titel} className="relative">
              <p className={`flex flex-wrap items-baseline gap-x-2 text-[13.5px] leading-snug ${ausrichtung}`} style={{ "--x": pos(s.ab) }}>
                <span className="font-semibold text-white">{s.titel}</span>
                <span className="text-white/55">seit {s.ab}</span>
              </p>
              <div className="relative mt-2 h-2.5 rounded-full bg-white/[0.06]">
                <span className={`absolute inset-y-0 right-0 rounded-full ${s.ton}`} style={{ left: pos(s.ab) }} />
                <span aria-hidden="true" className="absolute top-1/2 h-4 w-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-navy-950 bg-white" style={{ left: pos(s.ab) }} />
              </div>
              <p className={`mt-1.5 text-[12.5px] text-white/60 ${ausrichtung}`} style={{ "--x": pos(s.ab) }}>
                {s.text}
              </p>
            </li>
            );
          })}
        </ul>

        {/* Achse */}
        <div aria-hidden="true" className="relative mt-6 h-6 border-t border-white/15">
          {ticks.map((j) => (
            <span key={j} className="ov-num absolute top-2 -translate-x-1/2 text-[11.5px] text-white/50 max-sm:[&:nth-child(even)]:hidden" style={{ left: pos(j) }}>
              {j}
            </span>
          ))}
          {marken.map((j) => (
            <span key={`m${j}`} className="absolute -top-[5px] h-2.5 w-2.5 -translate-x-1/2 rounded-full bg-ov-300 ring-2 ring-navy-950" style={{ left: pos(j) }} />
          ))}
        </div>
      </div>
    </figure>
  );
}
import { Building2, Factory, Hammer, Sun, Zap } from "lucide-react";
import { GESELLSCHAFT } from "@/data/site";
import { cn } from "@/components/ui/cn";

/**
 * Struktur der Gruppe aus Sicht von ÖkoInvest – bewusst ohne
 * Beteiligungsquoten an ÖkoInvest selbst (nur belegte Angaben).
 * Ab lg ein Organigramm (Gruppe → vier Gesellschaften → Beteiligungen
 * unter ÖkoInvest), darunter eine eingerückte Baumliste.
 */
const SCHWESTERN = [
  { icon: Factory, titel: "ÖKOVOLT GmbH Solartechnik", text: "Muttergesellschaft in Türkheim – PV und Speicher für Gewerbe", land: "DE" },
  { icon: Factory, titel: "ÖKOVOLT Solartechnik GmbH", text: "Schwestergesellschaft in Ostermiething", land: "AT" },
  { icon: Hammer, titel: "Deutsche Solar & Rammtechnik GmbH", text: "Fundamente für Freiflächenanlagen", land: "DE" },
];
const OI = { icon: Sun, titel: GESELLSCHAFT.name, text: "Projektentwicklung, Projektbörse, virtuelles Kraftwerk", land: "AT" };

export default function GruppenGrafik({ className }) {
  return (
    <figure className={cn("relative rounded-[1.75rem] bg-white p-5 shadow-e3 ring-1 ring-ink-200/70 sm:p-7 md:rounded-[2rem] lg:p-10", className)}>
      <figcaption className="sr-only">Einordnung der ÖkoInvest GmbH in die ÖKOVOLT Gruppe mit ihren Beteiligungen</figcaption>
      <div aria-hidden="true" className="ov-grid-bg-light pointer-events-none absolute inset-0 rounded-[inherit] opacity-70" />

      {/* Organigramm ab lg */}
      <div className="relative hidden lg:block">
        <div className="mx-auto max-w-sm">
          <Knoten dunkel icon={Building2} titel="ÖKOVOLT Gruppe" text="Familiengeführt, seit 2010 im Solargeschäft" />
        </div>
        <Verteiler spalten={4} />
        <div className="grid grid-cols-4 gap-4">
          {SCHWESTERN.map((k) => (
            <Knoten key={k.titel} {...k} />
          ))}
          <Knoten gruen {...OI} />
        </div>
        {/* Beteiligungen unter ÖkoInvest: Linie aus Spalte 4 in die Spalten 3–4 */}
        <div className="grid grid-cols-4 gap-4">
          <p className="col-span-2 self-end pb-1 pr-8 text-[13px] leading-relaxed text-ink-500">
            Länderkürzel: Sitz der Gesellschaft. Anteile nennen wir nur dort, wo sie im Firmenbuch eingetragen sind.
          </p>
          <div className="col-span-2">
            <div aria-hidden="true" className="relative h-10">
              <span className="absolute right-[calc(25%-1px)] top-0 h-5 w-0.5 bg-ov-500" />
              <span className="absolute left-[25%] right-[25%] top-5 h-0.5 bg-ov-500" />
              <span className="absolute left-[calc(25%-1px)] top-5 h-5 w-0.5 bg-ov-500" />
              <span className="absolute right-[calc(25%-1px)] top-5 h-5 w-0.5 bg-ov-500" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              {GESELLSCHAFT.beteiligungen.map((b) => (
                <Knoten key={b.name} icon={Zap} titel={b.name} text={b.text} anteil={b.anteil} />
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Baumliste bis lg */}
      <div className="relative lg:hidden">
        <Knoten dunkel icon={Building2} titel="ÖKOVOLT Gruppe" text="Familiengeführt, seit 2010 im Solargeschäft" />
        <ul className="ml-5 border-l-2 border-ov-200 pl-4 pt-3">
          {SCHWESTERN.map((k) => (
            <li key={k.titel} className="relative pb-3">
              <Ast />
              <Knoten {...k} />
            </li>
          ))}
          <li className="relative">
            <Ast gruen />
            <Knoten gruen {...OI} />
            <ul className="ml-5 border-l-2 border-ov-400 pl-4 pt-3">
              {GESELLSCHAFT.beteiligungen.map((b) => (
                <li key={b.name} className="relative pb-3 last:pb-0">
                  <Ast gruen />
                  <Knoten icon={Zap} titel={b.name} text={b.text} anteil={b.anteil} />
                </li>
              ))}
            </ul>
          </li>
        </ul>
      </div>
    </figure>
  );
}

/** Verbindung von einem Knoten auf n Spalten (Linie in die Spaltenmitten) */
function Verteiler({ spalten }) {
  const halb = 100 / spalten / 2;
  return (
    <div aria-hidden="true" className="relative h-12">
      <span className="absolute left-1/2 top-0 h-6 w-0.5 -translate-x-1/2 bg-ov-300" />
      <span className="absolute top-6 h-0.5 bg-ov-300" style={{ left: `${halb}%`, right: `${halb}%` }} />
      {Array.from({ length: spalten }, (_, i) => (
        <span key={i} className={cn("absolute top-6 h-6 w-0.5 -translate-x-1/2", i === spalten - 1 ? "bg-ov-500" : "bg-ov-300")} style={{ left: `${halb + (i * 100) / spalten}%` }} />
      ))}
    </div>
  );
}

function Ast({ gruen }) {
  return <span aria-hidden="true" className={cn("absolute -left-4 top-7 h-0.5 w-4", gruen ? "bg-ov-400" : "bg-ov-200")} />;
}

function Knoten({ icon: Icon, titel, text, land, anteil, dunkel, gruen }) {
  return (
    <div
      className={cn(
        "relative flex h-full items-start gap-3 rounded-2xl p-4",
        dunkel ? "bg-navy-950 text-white shadow-e3" : gruen ? "ov-verlauf-gruen text-white shadow-[0_16px_36px_-14px_rgba(102,153,51,0.75)]" : "bg-white shadow-e1 ring-1 ring-ink-200/80"
      )}
    >
      <span className={cn("flex h-10 w-10 shrink-0 items-center justify-center rounded-xl", dunkel ? "bg-white/10 text-ov-300" : gruen ? "bg-white/15 text-white" : "bg-ov-50 text-ov-600 ring-1 ring-ov-100")}>
        <Icon aria-hidden="true" className="h-5 w-5" />
      </span>
      <div className="min-w-0">
        <p className={cn("font-display text-[15px] font-bold leading-snug", dunkel || gruen ? "text-white" : "text-ink-900")}>
          {titel}
          {land && <span className={cn("ml-1.5 inline-block rounded px-1.5 py-0.5 align-[2px] text-[10.5px] font-bold leading-none", dunkel || gruen ? "bg-white/15 text-white" : "bg-ink-100 text-ink-600")}>{land}</span>}
        </p>
        <p className={cn("mt-1 text-[13px] leading-snug", dunkel ? "text-white/65" : gruen ? "text-white/90" : "text-ink-600")}>{text}</p>
        {anteil && <p className="mt-2 inline-flex rounded-full bg-ov-50 px-2 py-0.5 text-[12px] font-semibold text-ov-700 ring-1 ring-ov-200">Anteil ÖkoInvest: {anteil}</p>}
      </div>
    </div>
  );
}
// Seitenkopf der Vertrauensseiten (/unternehmen, /kontakt, /prozess, /faq,
// /warum-oekoinvest, /referenzen) – gleiche Markensprache wie die Referenzseite
// /energiegemeinschaften/software: Nachtverlauf, Raster, Lichtkante, Bühne rechts.
import { ArrowRight, Check } from "lucide-react";
import Breadcrumbs from "@/components/ui/Breadcrumbs";
import Button from "@/components/ui/Button";
import { cn } from "@/components/ui/cn";

/**
 * props:
 *  breadcrumbs  [{ name, href }]
 *  hinweis      { label, text, kurz?, href } – Pill über der Headline (optional)
 *  eyebrow      Überzeile, falls kein Hinweis
 *  title        JSX, lead JSX/String
 *  actions      [{ label, href, variant? }] – erste = primär
 *  notiz        Kleiner Satz unter den Buttons
 *  chips        ["…"] – Kurzversprechen (mobil die ersten zwei)
 *  buehne       JSX rechts (ab lg zweispaltig, darunter gestapelt)
 *  mitLeiste    true: unten Platz für eine überlappende Faktenleiste
 *  schmal       true: ohne Bühne, Text breiter
 */
export default function NachtHero({
  breadcrumbs,
  hinweis,
  eyebrow,
  title,
  lead,
  actions = [],
  notiz,
  chips = [],
  buehne,
  mitLeiste = false,
  children,
  className,
}) {
  return (
    <section aria-labelledby="seiten-titel" className={cn("ov-verlauf-nacht ov-noise relative isolate overflow-hidden text-white", className)}>
      <div aria-hidden="true" className="ov-grid-bg absolute inset-0 -z-10 opacity-50" />
      <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 -z-10 h-px bg-gradient-to-r from-transparent via-ov-300/40 to-transparent" />
      <div aria-hidden="true" className="pointer-events-none absolute -left-40 -top-40 -z-10 h-[520px] w-[520px] rounded-full bg-ov-500/20 blur-[120px]" />
      <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 bottom-0 -z-10 h-40 bg-gradient-to-b from-transparent to-navy-950/50" />

      <div className={cn("ov-container pt-6 sm:pt-8 md:pt-10", mitLeiste ? "pb-24 md:pb-32" : "pb-16 md:pb-24")}>
        {breadcrumbs && <Breadcrumbs items={breadcrumbs} dark className="ov-hero-in mb-8 md:mb-12" />}

        <div className={cn("grid grid-cols-[minmax(0,1fr)] items-center gap-y-14", buehne && "lg:grid-cols-[minmax(0,0.92fr)_minmax(0,1.08fr)] lg:gap-x-12 xl:gap-x-16")}>
          <div className={buehne ? "max-w-[37rem]" : "max-w-3xl"}>
            {hinweis ? (
              <a
                href={hinweis.href}
                className="ov-hero-in group inline-flex max-w-full items-center gap-2.5 rounded-full bg-white/[0.06] py-1 pl-1 pr-3.5 text-[13px] text-white/85 ring-1 ring-inset ring-white/15 transition-colors hover:bg-white/10 hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-300"
                style={{ "--ov-delay": "40ms" }}
              >
                <span className="shrink-0 rounded-full bg-ov-300 px-2 py-0.5 text-[11px] font-bold uppercase tracking-[0.08em] text-navy-950">{hinweis.label}</span>
                <span className="min-w-0 truncate">
                  {hinweis.kurz ? (
                    <>
                      <span className="sm:hidden">{hinweis.kurz}</span>
                      <span className="max-sm:hidden">{hinweis.text}</span>
                    </>
                  ) : (
                    hinweis.text
                  )}
                </span>
                <ArrowRight aria-hidden="true" className="h-3.5 w-3.5 shrink-0 text-ov-300 transition-transform duration-200 group-hover:translate-x-0.5 motion-reduce:transition-none" />
              </a>
            ) : (
              eyebrow && (
                <p className="ov-hero-in ov-overline flex items-center gap-2 text-ov-300" style={{ "--ov-delay": "40ms" }}>
                  <span aria-hidden="true" className="h-1.5 w-1.5 rounded-full bg-ov-300" />
                  {eyebrow}
                </p>
              )
            )}

            <h1 id="seiten-titel" className="ov-h1 ov-hero-in mt-6 text-balance md:mt-8" style={{ "--ov-delay": "100ms" }}>
              {title}
            </h1>

            {lead && (
              <p className="ov-lead ov-hero-in mt-5 text-pretty text-white/75 md:mt-6" style={{ "--ov-delay": "180ms" }}>
                {lead}
              </p>
            )}

            {actions.length > 0 && (
              <div className="ov-hero-in mt-8 flex flex-col gap-3 sm:flex-row sm:items-center md:mt-10" style={{ "--ov-delay": "260ms" }}>
                {actions.map((a, i) => (
                  <Button key={a.label} href={a.href} size="lg" pfeil={i === 0} variant={a.variant || (i === 0 ? "primary" : "outlineLight")} className="w-full sm:w-auto">
                    {a.label}
                  </Button>
                ))}
              </div>
            )}
            {notiz && (
