  width: var(--ov-spot-groesse, 440px);
  height: var(--ov-spot-groesse, 440px);
  margin: calc(var(--ov-spot-groesse, 440px) / -2) 0 0 calc(var(--ov-spot-groesse, 440px) / -2);
  border-radius: 9999px;
  background: radial-gradient(closest-side, var(--ov-spot-farbe, rgba(102, 153, 51, 0.13)), transparent);
  transform: translate3d(var(--ov-mx, -999px), var(--ov-my, -999px), 0);
  opacity: 0;
  transition: opacity 320ms var(--ov-ease-out);
  will-change: transform;
}
.ov-spotlight[data-ton="dunkel"] { --ov-spot-farbe: rgba(174, 208, 131, 0.16); }
.ov-spotlight.ov-zeiger-an .ov-spot-licht::before { opacity: 1; }
@media (hover: none), (pointer: coarse), (prefers-reduced-motion: reduce) {
  .ov-spot-licht { display: none; }
}

/* ---------- Magnetisch: Primär-CTA folgt dem Zeiger um wenige Pixel ---------- */
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .ov-magnet {
    transform: translate3d(var(--ov-mag-x, 0px), var(--ov-mag-y, 0px), 0);
    transition: transform 420ms var(--ov-ease-feder);
  }
  .ov-magnet.ov-zeiger-an { transition-duration: 140ms; transition-timing-function: var(--ov-ease-out); }
}

/* ---------- Kipp-Karte: dezentes 3D-Kippen (max. 3°) ---------- */
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .ov-kipp {
    transform: perspective(1100px) rotateX(var(--ov-kx, 0deg)) rotateY(var(--ov-ky, 0deg));
    transition: transform 520ms var(--ov-ease-out);
  }
  .ov-kipp.ov-zeiger-an { transition-duration: 120ms; }
  .ov-kipp.ov-lift:hover,
  .ov-kipp.ov-card-hover:hover {
    transform: perspective(1100px) rotateX(var(--ov-kx, 0deg)) rotateY(var(--ov-ky, 0deg)) translate3d(0, -3px, 0);
  }
}

/* ---------- Parallax leicht (scroll-driven CSS, ohne JS) ---------- */
@keyframes ov-parallax {
  from { transform: translate3d(0, var(--ov-parallax, 32px), 0); }
  to { transform: translate3d(0, calc(var(--ov-parallax, 32px) * -1), 0); }
}
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    /* Longhands statt Kurzform: Lightning CSS verwirft sonst animation-timeline */
    .ov-parallax {
      animation-name: ov-parallax;
      animation-timing-function: linear;
      animation-fill-mode: both;
      animation-timeline: view();
      animation-range-start: cover 0%;
      animation-range-end: cover 100%;
    }
  }
}

/* ---------- ScrollFortschritt (Lesefortschritt oben) ---------- */
.ov-scroll-fortschritt {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 110;
  height: 3px;
  pointer-events: none;
  transform-origin: 0 50%;
