          <caption className="sr-only">Vergleich der Modelle Marktplatz, Makler und Entwickler-Plattform</caption>
          <colgroup>
            <col className="w-[22%]" />
            {spalten.map((s) => (
              <col key={s.id} />
            ))}
          </colgroup>
          <thead>
            <tr>
              <th scope="col" className="px-5 py-5 align-bottom text-[12px] font-semibold uppercase tracking-[0.14em] text-ink-500">
