                  {z.kriterium}
                </th>
                {z.werte.map((w, i) => (
                  <td key={spalten[i].id} className={cn("px-5 py-4 align-top", spalten[i].hervorheben && "bg-ov-50")}>
                    <span className="flex gap-2.5 text-[14px] leading-relaxed text-ink-700">
                      <Stufe stufe={w.stufe} />
